public class DocumentsController : ControllerBase
{
    private readonly AppDbContext _dbContext;
    private readonly IAuthorizationService _authService;

    public DocumentsController(AppDbContext dbContext, IAuthorizationService authService)
    {
        _dbContext = dbContext;
        _authService = authService;
    }

    [HttpPut("{id}")]
    public async Task<IActionResult> UpdateDocument(string id, UpdateDto dto)
    {
        var document = await _dbContext.Documents.FindAsync(id);
        if (document == null) return NotFound();

        // Check if the current user owns this document
        var result = await _authService.AuthorizeAsync(
            User, document, "CanEditDocument");

        if (!result.Succeeded)
        {
            return Forbid("You can only edit your own documents.");
        }

        document.Title = dto.Title;
        document.Content = dto.Content;
        document.UpdatedAt = DateTime.UtcNow;

        await _dbContext.SaveChangesAsync();
        return NoContent();
    }
}

// Requirement class
public class DocumentOwnerRequirement : IAuthorizationRequirement { }

// Handler with resource type
public class DocumentOwnerHandler : 
    AuthorizationHandler<DocumentOwnerRequirement, Document>
{
    protected override Task HandleRequirementAsync(
        AuthorizationHandlerContext context,
        DocumentOwnerRequirement requirement,
        Document document)
    {
        var userId = context.User.FindFirst(ClaimTypes.NameIdentifier)?.Value;

        if (userId != null && document.OwnerId == userId)
        {
            context.Succeed(requirement);
        }

        return Task.CompletedTask;
    }
}

