public class TenantDocumentHandler : 
    AuthorizationHandler<TenantDocumentRequirement, Document>
{
    private readonly AppDbContext _dbContext;

    public TenantDocumentHandler(AppDbContext dbContext)
    {
        _dbContext = dbContext;
    }

    protected override async Task HandleRequirementAsync(
        AuthorizationHandlerContext context,
        TenantDocumentRequirement requirement,
        Document document)
    {
        var userId = context.User.FindFirst(ClaimTypes.NameIdentifier)?.Value;
        if (string.IsNullOrEmpty(userId)) return;

        // Verify user's tenant matches document's tenant
        var userTenantId = await _dbContext.Users
            .Where(u => u.Id == userId)
            .Select(u => u.OrganizationId)
            .FirstOrDefaultAsync();

        if (userTenantId == document.OrganizationId)
        {
            context.Succeed(requirement);
        }
    }
}

import { useQuery } from '@tanstack/react-query';
import { useParams } from 'react-router-dom';

function DocumentPage() {
  const { id } = useParams<{ id: string }>();
  const { user } = useAuth();

  const { data: document, isLoading } = useQuery({
    queryKey: ['document', id],
    queryFn: () => fetchDocument(id!)
  });

  if (isLoading) return <div>Loading...</div>;
  if (!document) return <div>Document not found</div>;

  // Resource-based check: can this user edit this specific document?
  const canEdit = document.ownerId === user?.id;

  return (
    <div>
      <h1>{document.title}</h1>
      <p>{document.content}</p>
      {canEdit && (
        <button onClick={() => editDocument(document.id)}>
          Edit Document
        </button>
      )}
    </div>
  );
}

// C# Example with Modern Patterns
using System;
using System.Collections.Generic;
using System.Threading.Tasks;

namespace Example
{
    // Generic repository interface
    public interface IRepository<T> where T : class
    {
        Task<T?> GetByIdAsync(int id);
        Task<IEnumerable<T>> GetAllAsync();
        Task<T> CreateAsync(T entity);
        Task UpdateAsync(T entity);
        Task DeleteAsync(int id);
    }

    // Service with dependency injection
    public class UserService
    {
        private readonly IRepository<User> _repository;
        private readonly ILogger<UserService> _logger;

        public UserService(
            IRepository<User> repository,
            ILogger<UserService> logger)
        {
            _repository = repository;
            _logger = logger;
        }

        public async Task<User?> GetUserWithOrdersAsync(int userId)
        {
            try
            {
                _logger.LogInformation("Fetching user {UserId}", userId);
                var user = await _repository.GetByIdAsync(userId);

                if (user == null)
                {
                    _logger.LogWarning("User {UserId} not found", userId);
                    return null;
                }

                return user;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error fetching user {UserId}", userId);
                throw;
            }
        }
    }
}
